import {
  Column,
  CreateDateColumn,
  Entity,
  JoinColumn,
  ManyToOne,
  PrimaryGeneratedColumn,
} from 'typeorm';
import { WalletEntity } from './wallet.entity';

@Entity('wallet_transactions')
export class WalletTransactionEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ name: 'wallet_id', type: 'uuid' })
  walletId!: string;

  @ManyToOne(() => WalletEntity, (wallet) => wallet.transactions)
  @JoinColumn({ name: 'wallet_id' })
  wallet!: WalletEntity;

  @Column({ name: 'asset_code', type: 'varchar', length: 64 })
  assetCode!: string;

  @Column({ type: 'varchar', length: 32 })
  type!: string; // deposit, withdraw, freeze, unfreeze, transfer

  @Column({ type: 'varchar', length: 16 })
  direction!: 'credit' | 'debit';

  @Column({ type: 'decimal', precision: 36, scale: 18 })
  amount!: string;

  @Column({ name: 'balance_before', type: 'decimal', precision: 36, scale: 18 })
  balanceBefore!: string;

  @Column({ name: 'balance_after', type: 'decimal', precision: 36, scale: 18 })
  balanceAfter!: string;

  @Column({ name: 'reference_id', type: 'varchar', length: 128, nullable: true })
  referenceId?: string;

  @Column({ name: 'biz_tag', type: 'varchar', length: 64, nullable: true })
  bizTag?: string;

  @Column({ type: 'json', nullable: true })
  metadata?: Record<string, any>;

  @CreateDateColumn({ name: 'created_at' })
  createdAt!: Date;
}

