import * as cron from 'node-cron';
import { DataSource, LessThan } from 'typeorm';
import { PaymentEntity } from './payment.entity';
import { PaymentStatus } from '../common/dto/payment.dto';

export class PaymentExpirationScheduler {
  private task: cron.ScheduledTask | null = null;
  private dataSource: DataSource;

  constructor(dataSource: DataSource) {
    this.dataSource = dataSource;
  }

  start(): void {
    // 每分钟执行一次
    this.task = cron.schedule('* * * * *', async () => {
      try {
        await this.sweepExpired();
      } catch (error) {
        console.error('定时任务执行失败:', error);
      }
    });
    console.log('✅ 支付过期检查定时任务已启动');
  }

  stop(): void {
    if (this.task) {
      this.task.stop();
      this.task = null;
      console.log('⏹️ 支付过期检查定时任务已停止');
    }
  }

  private async sweepExpired(): Promise<number> {
    const paymentRepo = this.dataSource.getRepository(PaymentEntity);
    const now = new Date();
    const toExpire = await paymentRepo.find({
      where: {
        status: PaymentStatus.PENDING,
        expiresAt: LessThan(now),
      },
    });
    if (toExpire.length === 0) return 0;
    for (const p of toExpire) {
      p.status = PaymentStatus.EXPIRED;
    }
    await paymentRepo.save(toExpire);
    console.log(`⏰ 过期订单数量: ${toExpire.length}`);
    return toExpire.length;
  }
}

