import { Router, Request, Response } from 'express';
import { body, query, param } from 'express-validator';
import { PaymentService } from '../payment/payment.service';
import { ApiResponseDto } from '../common/dto/common.dto';
import { PaymentStatus, PaymentMethod, PaymentChannel } from '../common/dto/payment.dto';
import { validate } from '../common/middleware/validation.middleware';

export function createPaymentRoutes(paymentService: PaymentService): Router {
  const router = Router();

  /**
   * @swagger
   * /payment/create:
   *   post:
   *     summary: 创建支付订单
   *     description: 创建新的支付订单，返回订单信息
   *     tags:
   *       - 支付
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - amount
   *               - currency
   *               - channel
   *               - toAddress
   *             properties:
   *               amount:
   *                 type: number
   *                 minimum: 0.01
   *                 example: 100.5
   *               currency:
   *                 type: string
   *                 enum: [eth, usdt, usdc, btc]
   *                 example: usdt
   *               channel:
   *                 type: string
   *                 enum: [alipay, wechat, paypal, card, crypto]
   *                 example: alipay
   *               toAddress:
   *                 type: string
   *                 minLength: 42
   *                 maxLength: 64
   *                 example: 0x742d35Cc6634C0532925a3b8D4C9db96C4b4d8b6
   *               description:
   *                 type: string
   *                 example: 购买商品服务
   *               orderId:
   *                 type: string
   *                 example: PAY202408160001
   *     responses:
   *       201:
   *         description: 订单创建成功
   *       400:
   *         description: 请求参数错误
   */
  router.post(
    '/create',
    [
      body('amount').isFloat({ min: 0.01 }).withMessage('金额必须大于等于 0.01'),
      body('currency').isIn([PaymentMethod.ETH, PaymentMethod.USDT, PaymentMethod.USDC, PaymentMethod.BTC])
        .withMessage('无效的支付货币'),
      body('channel').isIn([PaymentChannel.ALIPAY, PaymentChannel.WECHAT, PaymentChannel.PAYPAL, PaymentChannel.CARD, PaymentChannel.CRYPTO])
        .withMessage('无效的支付通道'),
      body('toAddress').isString().isLength({ min: 1 }).withMessage('收款地址不能为空'),
      body('description').optional().isString(),
      body('orderId').optional().isString(),
      validate,
    ],
    async (req: Request, res: Response) => {
      try {
        const order = await paymentService.createPayment(req.body);
        res.status(201).json(ApiResponseDto.success(order, '支付订单创建成功'));
      } catch (error: any) {
        res.status(400).json(ApiResponseDto.error(error.message || '创建订单失败', 400));
      }
    }
  );

  /**
   * @swagger
   * /payment/{orderId}:
   *   get:
   *     summary: 获取支付订单详情
   *     description: 根据订单ID获取订单的详细信息
   *     tags:
   *       - 支付
   *     parameters:
   *       - in: path
   *         name: orderId
   *         required: true
   *         schema:
   *           type: string
   *         example: 507f1f77bcf86cd799439011
   *     responses:
   *       200:
   *         description: 获取成功
   *       404:
   *         description: 订单不存在
   */
  router.get(
    '/:orderId',
    [
      param('orderId').isString().notEmpty().withMessage('订单ID不能为空'),
      validate,
    ],
    async (req: Request, res: Response) => {
      try {
        const order = await paymentService.getPaymentOrder(req.params.orderId);
        res.json(ApiResponseDto.success(order, '获取订单成功'));
      } catch (error: any) {
        res.status(404).json(ApiResponseDto.error(error.message || '订单不存在', 404));
      }
    }
  );

  /**
   * @swagger
   * /payment:
   *   get:
   *     summary: 查询支付订单列表
   *     description: 分页查询支付订单，支持状态和货币筛选
   *     tags:
   *       - 支付
   *     parameters:
   *       - in: query
   *         name: status
   *         schema:
   *           type: string
   *           enum: [pending, processing, success, failed, cancelled, expired]
   *       - in: query
   *         name: currency
   *         schema:
   *           type: string
   *           enum: [eth, usdt, usdc, btc]
   *       - in: query
   *         name: channel
   *         schema:
   *           type: string
   *           enum: [alipay, wechat, paypal, card, crypto]
   *       - in: query
   *         name: orderId
   *         schema:
   *           type: string
   *       - in: query
   *         name: page
   *         schema:
   *           type: integer
   *           minimum: 1
   *           default: 1
   *       - in: query
   *         name: limit
   *         schema:
   *           type: integer
   *           minimum: 1
   *           maximum: 100
   *           default: 10
   *     responses:
   *       200:
   *         description: 查询成功
   */
  router.get(
    '/',
    [
      query('status').optional().isIn([
        PaymentStatus.PENDING,
        PaymentStatus.PROCESSING,
        PaymentStatus.SUCCESS,
        PaymentStatus.FAILED,
        PaymentStatus.CANCELLED,
        PaymentStatus.EXPIRED,
      ]),
      query('currency').optional().isIn([PaymentMethod.ETH, PaymentMethod.USDT, PaymentMethod.USDC, PaymentMethod.BTC]),
      query('channel').optional().isIn([PaymentChannel.ALIPAY, PaymentChannel.WECHAT, PaymentChannel.PAYPAL, PaymentChannel.CARD, PaymentChannel.CRYPTO]),
      query('orderId').optional().isString(),
      query('page').optional().isInt({ min: 1 }).withMessage('页码必须大于等于 1'),
      query('limit').optional().isInt({ min: 1, max: 100 }).withMessage('每页数量必须在 1-100 之间'),
      validate,
    ],
    async (req: Request, res: Response) => {
      try {
        const { items, total, page, limit } = await paymentService.getPaymentOrders(
          req.query,
          { page: Number(req.query.page) || 1, limit: Number(req.query.limit) || 10 }
        );
        res.json(ApiResponseDto.success(
          {
            items,
            total,
            page,
            limit,
            totalPages: Math.ceil(total / limit),
          },
          '查询订单列表成功'
        ));
      } catch (error: any) {
        res.status(400).json(ApiResponseDto.error(error.message || '查询失败', 400));
      }
    }
  );

  /**
   * @swagger
   * /payment/confirm:
   *   post:
   *     summary: 确认支付
   *     description: 确认区块链交易，更新订单状态为成功
   *     tags:
   *       - 支付
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             required:
   *               - orderId
   *               - txHash
   *             properties:
   *               orderId:
   *                 type: string
   *                 example: 507f1f77bcf86cd799439011
   *               txHash:
   *                 type: string
   *                 example: 0x1234567890abcdef...
   *               blockNumber:
   *                 type: number
   *                 example: 12345678
   *     responses:
   *       200:
   *         description: 确认成功
   *       400:
   *         description: 请求参数错误
   *       404:
   *         description: 订单不存在
   */
  router.post(
    '/confirm',
    [
      body('orderId').isString().notEmpty().withMessage('订单ID不能为空'),
      body('txHash').isString().notEmpty().withMessage('交易哈希不能为空'),
      body('blockNumber').optional().isInt({ min: 0 }),
      validate,
    ],
    async (req: Request, res: Response) => {
      try {
        const order = await paymentService.confirmPayment(req.body);
        res.json(ApiResponseDto.success(order, '支付确认成功'));
      } catch (error: any) {
        const status = error.message.includes('不存在') ? 404 : 400;
        res.status(status).json(ApiResponseDto.error(error.message || '确认支付失败', status));
      }
    }
  );

  /**
   * @swagger
   * /payment/{orderId}/cancel:
   *   post:
   *     summary: 取消支付订单
   *     description: 取消待处理的支付订单
   *     tags:
   *       - 支付
   *     parameters:
   *       - in: path
   *         name: orderId
   *         required: true
   *         schema:
   *           type: string
   *         example: 507f1f77bcf86cd799439011
   *     responses:
   *       200:
   *         description: 取消成功
   *       400:
   *         description: 订单状态不允许取消
   *       404:
   *         description: 订单不存在
   */
  router.post(
    '/:orderId/cancel',
    [
      param('orderId').isString().notEmpty().withMessage('订单ID不能为空'),
      validate,
    ],
    async (req: Request, res: Response) => {
      try {
        const order = await paymentService.cancelPayment(req.params.orderId);
        res.json(ApiResponseDto.success(order, '订单取消成功'));
      } catch (error: any) {
        const status = error.message.includes('不存在') ? 404 : 400;
        res.status(status).json(ApiResponseDto.error(error.message || '取消订单失败', status));
      }
    }
  );

  /**
   * @swagger
   * /payment/stats/overview:
   *   get:
   *     summary: 获取支付统计信息
   *     description: 获取支付总金额、订单数量等统计信息
   *     tags:
   *       - 支付
   *     responses:
   *       200:
   *         description: 获取成功
   */
  router.get('/stats/overview', async (req: Request, res: Response) => {
    try {
      const stats = await paymentService.getPaymentStats();
      res.json(ApiResponseDto.success(stats, '获取统计信息成功'));
    } catch (error: any) {
      res.status(400).json(ApiResponseDto.error(error.message || '获取统计信息失败', 400));
    }
  });

  return router;
}

