import Decimal from 'decimal.js';
import { DataSource, Repository } from 'typeorm';
import { AssetEntity } from './asset.entity';
import { WalletEntity } from './wallet.entity';
import { WalletTransactionEntity } from './wallet-transaction.entity';
import { DEFAULT_ASSETS } from './default-assets';

Decimal.set({ precision: 36, rounding: Decimal.ROUND_DOWN });

export interface WalletOperationOptions {
  referenceId?: string;
  metadata?: Record<string, any>;
  bizTag?: string;
}

export class WalletService {
  private assetRepository: Repository<AssetEntity>;
  private walletRepository: Repository<WalletEntity>;
  private txRepository: Repository<WalletTransactionEntity>;

  constructor(private readonly dataSource: DataSource) {
    this.assetRepository = dataSource.getRepository(AssetEntity);
    this.walletRepository = dataSource.getRepository(WalletEntity);
    this.txRepository = dataSource.getRepository(WalletTransactionEntity);
  }

  /**
   * 初始化默认资产配置
   */
  async ensureDefaultAssets(): Promise<void> {
    for (const asset of DEFAULT_ASSETS) {
      const exists = await this.assetRepository.findOne({
        where: { assetCode: asset.assetCode },
      });

      if (!exists) {
        const entity = this.assetRepository.create({
          assetCode: asset.assetCode,
          displayName: asset.displayName,
          type: asset.type,
          precision: asset.precision,
          metadata: asset.metadata,
        });
        await this.assetRepository.save(entity);
      }
    }
  }

  async listAssets(): Promise<AssetEntity[]> {
    return this.assetRepository.find({ where: { isActive: true } });
  }

  async getWallets(userId: string): Promise<WalletEntity[]> {
    return this.walletRepository.find({
      where: { userId },
      order: { assetCode: 'ASC' },
    });
  }

  async getWallet(userId: string, assetCode: string): Promise<WalletEntity | null> {
    return this.walletRepository.findOne({
      where: { userId, assetCode },
    });
  }

  async getTransactions(userId: string, assetCode: string, limit = 20): Promise<WalletTransactionEntity[]> {
    const wallet = await this.getWallet(userId, assetCode);
    if (!wallet) {
      return [];
    }
    return this.txRepository.find({
      where: { walletId: wallet.id },
      order: { createdAt: 'DESC' },
      take: limit,
    });
  }

  async deposit(userId: string, assetCode: string, amount: string, options: WalletOperationOptions = {}): Promise<WalletEntity> {
    return this.adjustBalance(userId, assetCode, amount, 'deposit', 'credit', options);
  }

  async withdraw(userId: string, assetCode: string, amount: string, options: WalletOperationOptions = {}): Promise<WalletEntity> {
    return this.adjustBalance(userId, assetCode, amount, 'withdraw', 'debit', options);
  }

  private async adjustBalance(
    userId: string,
    assetCode: string,
    rawAmount: string,
    type: string,
    direction: 'credit' | 'debit',
    options: WalletOperationOptions
  ): Promise<WalletEntity> {
    const amount = new Decimal(rawAmount);
    if (amount.lte(0)) {
      throw new Error('金额必须大于 0');
    }

    const queryRunner = this.dataSource.createQueryRunner();
    await queryRunner.connect();
    await queryRunner.startTransaction();

    try {
      const walletRepo = queryRunner.manager.getRepository(WalletEntity);
      const txRepo = queryRunner.manager.getRepository(WalletTransactionEntity);

      let wallet = await walletRepo.findOne({
        where: { userId, assetCode },
        lock: { mode: 'pessimistic_write' },
      });

      if (!wallet) {
        wallet = walletRepo.create({
          userId,
          assetCode,
          availableBalance: '0',
          frozenBalance: '0',
          walletType: 'primary',
          status: 'active',
        });
        wallet = await walletRepo.save(wallet);
      }

      const asset = await this.assetRepository.findOne({ where: { assetCode } });
      if (!asset) {
        throw new Error(`资产 ${assetCode} 未配置`);
      }

      const currentBalance = new Decimal(wallet.availableBalance || '0');
      const nextBalance =
        direction === 'credit' ? currentBalance.add(amount) : currentBalance.minus(amount);

      if (nextBalance.lt(0)) {
        throw new Error('余额不足');
      }

      wallet.availableBalance = nextBalance.toFixed(asset.precision);
      wallet = await walletRepo.save(wallet);

      const tx = txRepo.create({
        walletId: wallet.id,
        assetCode,
        type,
        direction,
        amount: amount.toFixed(asset.precision),
        balanceBefore: currentBalance.toFixed(asset.precision),
        balanceAfter: nextBalance.toFixed(asset.precision),
        referenceId: options.referenceId,
        metadata: options.metadata,
        bizTag: options.bizTag,
      });
      await txRepo.save(tx);

      await queryRunner.commitTransaction();
      return wallet;
    } catch (error) {
      await queryRunner.rollbackTransaction();
      throw error;
    } finally {
      await queryRunner.release();
    }
  }
}

