import {
  Column,
  CreateDateColumn,
  Entity,
  JoinColumn,
  ManyToOne,
  OneToMany,
  PrimaryGeneratedColumn,
  Unique,
  UpdateDateColumn,
} from 'typeorm';
import { AssetEntity } from './asset.entity';
import { WalletTransactionEntity } from './wallet-transaction.entity';

@Entity('wallets')
@Unique(['userId', 'assetCode', 'walletType'])
export class WalletEntity {
  @PrimaryGeneratedColumn('uuid')
  id!: string;

  @Column({ name: 'user_id', type: 'varchar', length: 64 })
  userId!: string;

  @Column({ name: 'wallet_type', type: 'varchar', length: 32, default: 'primary' })
  walletType!: string;

  @Column({ name: 'asset_code', type: 'varchar', length: 64 })
  assetCode!: string;

  @ManyToOne(() => AssetEntity, (asset) => asset.wallets)
  @JoinColumn({ name: 'asset_code', referencedColumnName: 'assetCode' })
  asset!: AssetEntity;

  @Column({ name: 'available_balance', type: 'decimal', precision: 36, scale: 18, default: 0 })
  availableBalance!: string;

  @Column({ name: 'frozen_balance', type: 'decimal', precision: 36, scale: 18, default: 0 })
  frozenBalance!: string;

  @Column({ type: 'varchar', length: 20, default: 'active' })
  status!: 'active' | 'frozen';

  @Column({ type: 'json', nullable: true })
  metadata?: Record<string, any>;

  @CreateDateColumn({ name: 'created_at' })
  createdAt!: Date;

  @UpdateDateColumn({ name: 'updated_at' })
  updatedAt!: Date;

  @OneToMany(() => WalletTransactionEntity, (tx) => tx.wallet)
  transactions!: WalletTransactionEntity[];
}

