import { Repository, FindOptionsWhere, Like, DataSource } from 'typeorm';
import {
  CreatePaymentDto,
  PaymentOrderDto,
  ConfirmPaymentDto,
  QueryPaymentDto,
  PaymentStatus,
} from '../common/dto/payment.dto';
import { PaginationDto } from '../common/dto/common.dto';
import { PaymentEntity } from './payment.entity';
import { GatewayFactory } from './providers/gateway.factory';
import { QrService } from '../common/qr.service';
import { env } from '../config/env';

export class PaymentService {
  private paymentRepo: Repository<PaymentEntity>;
  private gatewayFactory: GatewayFactory;
  private qrService: QrService;

  constructor(dataSource: DataSource) {
    this.paymentRepo = dataSource.getRepository(PaymentEntity);
    this.gatewayFactory = new GatewayFactory();
    this.qrService = new QrService();
  }

  async createPayment(
    createPaymentDto: CreatePaymentDto,
  ): Promise<PaymentOrderDto> {
    const orderId = createPaymentDto.orderId || `PAY${Date.now()}`;
    const now = new Date();
    const expiresAt = new Date(now.getTime() + env.payment.expireMinutes * 60 * 1000);
    const entity = this.paymentRepo.create({
      amount: createPaymentDto.amount,
      currency: createPaymentDto.currency,
      channel: createPaymentDto.channel,
      toAddress: createPaymentDto.toAddress,
      description: createPaymentDto.description ?? null,
      orderId,
      status: PaymentStatus.PENDING,
      expiresAt,
    });
    const saved = await this.paymentRepo.save(entity);

    // 调用对应网关创建订单（占位实现）
    try {
      const gateway = this.gatewayFactory.get(createPaymentDto.channel);
      const gatewayResult = await gateway.create({
        orderId: saved.orderId,
        amount: Number(saved.amount),
        currency: saved.currency,
        description: saved.description ?? undefined,
      });
      const payLink = gatewayResult.paymentUrl || gatewayResult.qrCodeUrl || '';
      const qr = payLink ? await this.qrService.generateDataUrl(payLink) : undefined;
      saved.paymentUrl = payLink || null;
      saved.qrCodeDataUrl = qr || null;
      await this.paymentRepo.save(saved);
      const dto = this.mapEntityToDto(saved);
      return dto;
    } catch (e) {
      // 网关创建失败不影响本地记录创建，可根据需要回滚或标记失败
      const dto = this.mapEntityToDto(saved);
      return dto;
    }
  }

  async getPaymentOrder(orderIdOrId: string): Promise<PaymentOrderDto> {
    // 尝试先通过 id (UUID) 查找，如果没找到则通过 orderId 查找
    let payment = await this.paymentRepo.findOne({ where: { id: orderIdOrId } });
    if (!payment) {
      payment = await this.paymentRepo.findOne({ where: { orderId: orderIdOrId } });
    }
    if (!payment) {
      throw new Error(`订单 ${orderIdOrId} 不存在`);
    }
    return this.mapEntityToDto(payment);
  }

  async getPaymentOrders(
    query: QueryPaymentDto,
    pagination: PaginationDto,
  ): Promise<{
    items: PaymentOrderDto[];
    total: number;
    page: number;
    limit: number;
  }> {
    const page = pagination.page || 1;
    const limit = pagination.limit || 10;

    const where: FindOptionsWhere<PaymentEntity> = {};
    if (query.status) where.status = query.status;
    if (query.currency) where.currency = query.currency;
    if ((query as any).channel) (where as any).channel = (query as any).channel;
    if (query.orderId) where.orderId = Like(`%${query.orderId}%`);

    const [rows, total] = await this.paymentRepo.findAndCount({
      where,
      order: { createdAt: 'DESC' },
      skip: (page - 1) * limit,
      take: limit,
    });

    return {
      items: rows.map((r) => this.mapEntityToDto(r)),
      total,
      page,
      limit,
    };
  }

  async confirmPayment(
    confirmPaymentDto: ConfirmPaymentDto,
  ): Promise<PaymentOrderDto> {
    const payment = await this.paymentRepo.findOne({
      where: { orderId: confirmPaymentDto.orderId },
    });
    if (!payment) {
      throw new Error(`订单 ${confirmPaymentDto.orderId} 不存在`);
    }
    if (payment.expiresAt && payment.expiresAt.getTime() < Date.now()) {
      payment.status = PaymentStatus.EXPIRED;
      await this.paymentRepo.save(payment);
      throw new Error('订单已过期');
    }
    if (payment.status !== PaymentStatus.PENDING) {
      throw new Error(
        `订单状态为 ${payment.status}，无法确认支付`,
      );
    }
    payment.status = PaymentStatus.SUCCESS;
    const saved = await this.paymentRepo.save(payment);
    return this.mapEntityToDto(saved);
  }

  async cancelPayment(orderIdOrId: string): Promise<PaymentOrderDto> {
    // 尝试先通过 id (UUID) 查找，如果没找到则通过 orderId 查找
    let payment = await this.paymentRepo.findOne({ where: { id: orderIdOrId } });
    if (!payment) {
      payment = await this.paymentRepo.findOne({ where: { orderId: orderIdOrId } });
    }
    if (!payment) {
      throw new Error(`订单 ${orderIdOrId} 不存在`);
    }
    if (payment.status !== PaymentStatus.PENDING) {
      throw new Error(`订单状态为 ${payment.status}，无法取消`);
    }
    payment.status = PaymentStatus.CANCELLED;
    const saved = await this.paymentRepo.save(payment);
    return this.mapEntityToDto(saved);
  }

  async getPaymentStats(): Promise<any> {
    const totalOrders = await this.paymentRepo.count();
    const successOrders = await this.paymentRepo.count({
      where: { status: PaymentStatus.SUCCESS },
    });
    const totalAmountRaw = await this.paymentRepo
      .createQueryBuilder('p')
      .select('COALESCE(SUM(p.amount), 0)', 'sum')
      .where('p.status = :status', { status: PaymentStatus.SUCCESS })
      .getRawOne<{ sum: string }>();

    return {
      totalOrders,
      totalAmount: Number(totalAmountRaw?.sum || 0),
      successRate:
        totalOrders > 0
          ? Number(((successOrders / totalOrders) * 100).toFixed(2))
          : 0,
    };
  }

  private mapEntityToDto(e: PaymentEntity): PaymentOrderDto {
    return {
      id: e.id,
      amount: Number(e.amount),
      currency: e.currency,
      channel: e.channel,
      toAddress: e.toAddress,
      status: e.status,
      description: e.description ?? '',
      orderId: e.orderId,
      createdAt: e.createdAt.toISOString(),
      updatedAt: e.updatedAt.toISOString(),
      expiresAt: e.expiresAt.toISOString(),
      paymentUrl: e.paymentUrl ?? undefined,
      qrCodeDataUrl: e.qrCodeDataUrl ?? undefined,
    };
  }
}

