import { DataSource } from 'typeorm';
import { PaymentEntity } from '../payment/payment.entity';
import { AssetEntity } from '../wallet/asset.entity';
import { WalletEntity } from '../wallet/wallet.entity';
import { WalletTransactionEntity } from '../wallet/wallet-transaction.entity';

export const AppDataSource = new DataSource({
  type: 'sqlite',
  database: process.env.SQLITE_DB_PATH || 'mxmpay.sqlite',
  synchronize: true,
  entities: [PaymentEntity, AssetEntity, WalletEntity, WalletTransactionEntity],
  logging: process.env.NODE_ENV === 'development',
});

